8: function validResponse(request, response, ruleIds) {
9:   return response && typeof response === 'object' && !Array.isArray(response)
10:     && Object.keys(response).sort().join(',') === RESPONSE_KEYS
11:     && response.schema === 'aleph.decision.v1'
12:     && response.requestId === request.requestId
