20: // Local practice only. The class engine and the server judge validate live requests separately.
21: export async function checkDecider({ decide, ruleIds }) {
22:   if (typeof decide !== 'function' || !Array.isArray(ruleIds)
23:       || !ruleIds.includes('device_registered')) {
24:     throw new Error('6단계 device_registered 규칙을 먼저 구현하고 RULE_IDS에 적어 주세요.');
25:   }
26:   const { normal, suspicious } = fixtureRequests();
27:   const checks = [
28:     { name: '등록 기기의 정상 요청', request: normal, decision: 'allow' },
29:     { name: '미등록 기기의 가상 요청', request: { ...normal, requestId: randomUUID(),
30:       deviceRegistered: false }, decision: 'deny', reasonCode: 'device_not_registered' },
31:   ];
32:   if (ruleIds.includes('step_up_required')) {
33:     checks.push(
34:       { name: '복합 이상 접속', request: suspicious, decision: 'step_up',
35:         reasonCode: 'step_up_required' },
36:       { name: '다시 확인한 복합 이상 접속', request: { ...suspicious,
37:         requestId: randomUUID(), stepUp: { verified: true, authAgeSeconds: 60 } },
38:       decision: 'allow' },
39:     );
40:   }
41:   const results = [];
42:   for (const item of checks) {
43:     const response = await decide(item.request);
44:     const valid = validResponse(item.request, response, ruleIds)
45:       && response.decision === item.decision
46:       && (!item.reasonCode || response.reasonCode === item.reasonCode);
47:     results.push({ name: item.name, passed: valid });
48:   }
49:   return results;
50: }
51: 
52: if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
53:   try {
54:     const { decide, RULE_IDS } = await import('../src/decider.mjs');
55:     const results = await checkDecider({ decide, ruleIds: RULE_IDS });
56:     for (const item of results) process.stdout.write(`${item.passed ? '통과' : '확인 필요'} · ${item.name}\n`);
57:     process.stdout.write('이 명령은 가상 요청으로 연습하며 심판 통과 증거가 아닙니다.\n');
58:     if (results.some(item => !item.passed)) process.exitCode = 1;
59:   } catch (error) {
60:     process.stderr.write(`판정기 연습 첫 오류: ${error.message}\n`);
